import { CommonTypeInfo, TransactionStatusType } from '@cetus/types/src/common-types'
import { Box, Image, Text, VStack } from '@chakra-ui/react'

type ModalDescriptionProps = {
  status?: TransactionStatusType
  info?: CommonTypeInfo | undefined
}

export function ModalDescription(props: ModalDescriptionProps) {
  const { status = 'confirmation', info } = props

  const description = info?.modalDescriptionText
  const iconUrl = info?.iconUrl

  // 待确认 / 已提交
  if (status === 'confirmation' || status === 'submitted') {
    return (
      <>
        <VStack gap="20px">
          {iconUrl && <Image src={iconUrl} w="100px" h="100px" alt="icon" borderRadius="8px" objectFit="cover" objectPosition="center" />}
          <Text color="text_caption">{description}</Text>
        </VStack>
      </>
    )
  }

  // 失败
  if (status === 'rejected') {
    return (
      <VStack gap="8px">
        {iconUrl && <Image src={iconUrl} w="100px" h="100px" alt="icon" borderRadius="8px" objectFit="cover" objectPosition="center" />}
        <Box h="12px" />
        <Text color="text_caption" fontSize="16px">
          Transaction failed
        </Text>
        <Text color="primary_red">{description}</Text>
      </VStack>
    )
  }

  // 成功
  if (status === 'success') {
    return (
      <>
        <VStack gap="8px">
          {iconUrl && <Image src={iconUrl} w="100px" h="100px" alt="icon" borderRadius="8px" objectFit="cover" objectPosition="center" />}
          <Box h="12px" />
          <Text color="text_caption" fontSize="16px">
            Transaction Completed
          </Text>
          <Text color="primary">{description}</Text>
        </VStack>
      </>
    )
  }

  return <></>
}
