import { ToastType } from '@cetus/types'
import { Button, Heading, Link, Modal, ModalBody, ModalCloseButton, ModalContent, ModalHeader, ModalOverlay, Text, VStack } from '@chakra-ui/react'
import { useMemo } from 'react'
import { ModalDescription } from './ModalDescription'

type TransactionProps = {
  isOpen: boolean
  onClose: () => void
} & ToastType

export default function TransactionModal(props: TransactionProps) {
  console.log('🚀 ~ file: TransactionModal.tsx:13 ~ TransactionModal ~ props:', props)

  const { status = 'confirmation', isOpen, onClose, link, getShowInfo } = props

  const showInfo = useMemo(() => {
    if (getShowInfo) {
      return getShowInfo(status)
    }
    return undefined
  }, [status])

  return (
    <Modal isOpen={isOpen} onClose={onClose} isCentered>
      <ModalOverlay />
      <ModalContent>
        {/* 标题 */}
        <ModalHeader>
          <Heading fontWeight="500" fontSize="16px">
            {showInfo?.modalTitleText}
          </Heading>
        </ModalHeader>
        <ModalCloseButton />
        <ModalBody>
          <VStack gap="8px" pb="24px" pt="28px" w="100%">
            {/* 描述 */}
            <ModalDescription info={showInfo} status={status} />
            {/* 钱包确认提示 */}
            {status === 'confirmation' && <Text>Confirm this transaction in your wallet</Text>}
            {/* 钱包确认已确认 */}
            {status === 'submitted' && <Text>Transaction in progress</Text>}
            {/* 交易成功 */}
            {(status === 'success' || status === 'rejected') && (
              <VStack mt="5px" gap="16px">
                {/* 区块游览器 */}
                {link && (
                  <Link href={link} target="_blank" color="primary_green" fontSize="sm" textDecoration={status === 'success' ? 'none' : 'none'}>
                    View on Explorer
                  </Link>
                )}
                {/* 关闭按钮 */}
                <Button
                  fontSize="14px"
                  w="226px"
                  onClick={() => {
                    onClose()
                    if (showInfo?.modalConfirmButtonClick) {
                      showInfo.modalConfirmButtonClick(0)
                    }
                  }}
                >
                  {(showInfo &&
                    showInfo.modalConfirmButtonText &&
                    showInfo.modalConfirmButtonText.length > 0 &&
                    showInfo?.modalConfirmButtonText[0]) ||
                    'Close'}
                </Button>
              </VStack>
            )}
          </VStack>
        </ModalBody>
      </ModalContent>
    </Modal>
  )
}
